import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.SUPABASE_POOLER_URL,
  max: 20,  // Max connections in pool
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

export async function queryDatabase(sql: string, params: any[]) {
